import { Chessground } from '../src/chessground';

// jsdom has no ResizeObserver; install a fake that tracks observe/disconnect so we
// can assert the observer lifecycle independently of any DOM size change.
class FakeResizeObserver {
  static active = 0; // observers observing a target (not yet disconnected)
  target?: Element;
  constructor(_cb: () => void) {}
  observe(target: Element): void {
    this.target = target;
    FakeResizeObserver.active++;
  }
  disconnect(): void {
    if (this.target) FakeResizeObserver.active--;
    this.target = undefined;
  }
}

beforeEach(() => {
  (FakeResizeObserver.active as number) = 0;
  (window as unknown as { ResizeObserver: typeof FakeResizeObserver }).ResizeObserver =
    FakeResizeObserver;
});

test('destroy disconnects the ResizeObserver (no leak on destroy)', () => {
  for (let i = 0; i < 100; i++) {
    const wrap = document.createElement('div');
    wrap.style.cssText = 'width:200px;height:200px';
    document.body.appendChild(wrap);
    const cg = Chessground(wrap, { viewOnly: true });
    cg.destroy();
    wrap.remove();
  }
  expect(FakeResizeObserver.active).toBe(0);
});

test('redrawAll disconnects the previous ResizeObserver (no leak on redraw)', () => {
  const wrap = document.createElement('div');
  wrap.style.cssText = 'width:200px;height:200px';
  document.body.appendChild(wrap);
  const cg = Chessground(wrap, { viewOnly: true });
  for (let i = 0; i < 50; i++) cg.redrawAll();
  // only the current wrap is observed, all previous observers disconnected
  expect(FakeResizeObserver.active).toBe(1);
  cg.destroy();
  expect(FakeResizeObserver.active).toBe(0);
  wrap.remove();
});

